import { Controller, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const STATUSES = ['대기', '승인', '처리완료'];
const DATE_PATTERN = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_APPOINTMENT_INPUT', message);
}

// 숫자 ID: 양의 정수 또는 숫자 문자열. 없으면 null
function optionalId(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^\d+$/.test(value)) {
    return value;
  }
  throw invalid(label + ' 형식이 올바르지 않습니다.');
}

function optionalText(value: unknown, label: string, max: number): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

function optionalDate(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || !DATE_PATTERN.test(value)) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01302Controller {
  @Post('/personnel-appointments')
  @HttpCode(200)
  async createPersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const employeeId = optionalId(data['employeeId'], '대상 임직원');
    if (employeeId === null) {
      throw invalid('대상 임직원은 필수입니다.');
    }
    const appointmentType = optionalText(data['appointmentType'], '발령 구분', 50);
    if (appointmentType === null) {
      throw invalid('발령 구분은 필수입니다.');
    }
    const appointmentDate = optionalDate(data['appointmentDate'], '발령일자');
    if (appointmentDate === null) {
      throw invalid('발령일자는 필수입니다.');
    }
    const departmentId = optionalId(data['departmentId'], '발령 후 소속 부서');
    const newPositionName = optionalText(data['newPositionName'], '발령 후 직위', 100);

    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '인사정보가 존재하지 않는 임직원입니다.');
      }
      if (departmentId !== null) {
        const departments = await db.query(
          'SELECT department_id AS "departmentId" FROM department WHERE department_id = CAST(:departmentId AS bigint)',
          { departmentId },
        );
        if (departments.length === 0) {
          throw invalid('발령 후 소속 부서가 존재하지 않습니다.');
        }
      }
      // 초기 발령상태는 고정값 '대기' (BEHAVIOR.md 값의 출처)
      const rows = await db.query(
        'INSERT INTO personnel_appointment '
          + '(employee_id, department_id, appointment_type, appointment_date, new_position_name, status, created_at, updated_at) '
          + "VALUES (CAST(:employeeId AS bigint), CAST(:departmentId AS bigint), :appointmentType, CAST(:appointmentDate AS date), :newPositionName, '대기', now(), now()) "
          + 'RETURNING personnel_appointment_id AS "personnelAppointmentId", status AS "status"',
        { employeeId, departmentId, appointmentType, appointmentDate, newPositionName },
      );
      return rows[0];
    });
  }

  @Patch('/personnel-appointments/:personnelAppointmentId')
  async updatePersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['personnelAppointmentId'];
    if (!/^\d+$/.test(id)) {
      throw invalid('인사발령 ID 형식이 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const appointmentType = optionalText(data['appointmentType'], '발령 구분', 50);
    const appointmentDate = optionalDate(data['appointmentDate'], '발령일자');
    const departmentId = optionalId(data['departmentId'], '발령 후 소속 부서');
    const newPositionName = optionalText(data['newPositionName'], '발령 후 직위', 100);
    const status = optionalText(data['status'], '발령 상태', 20);
    if (status !== null && !STATUSES.includes(status)) {
      throw invalid('허용되지 않는 발령 상태입니다.');
    }

    return transaction(async (db) => {
      const current = await db.query(
        'SELECT status AS "status" FROM personnel_appointment WHERE personnel_appointment_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (current.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '발령 대상자가 존재하지 않습니다.');
      }
      if (current[0]['status'] === '처리완료') {
        throw new ApiError(409, 'APPOINTMENT_ALREADY_PROCESSED', '처리완료된 대상자는 수정할 수 없습니다. 정해진 절차가 필요합니다.');
      }
      if (departmentId !== null) {
        const departments = await db.query(
          'SELECT department_id AS "departmentId" FROM department WHERE department_id = CAST(:departmentId AS bigint)',
          { departmentId },
        );
        if (departments.length === 0) {
          throw invalid('발령 후 소속 부서가 존재하지 않습니다.');
        }
      }
      // 가정: 처리완료로 바꿀 때 처리일자는 오늘, 처리자는 현재 사용자 (값의 출처 미정)
      const rows = await db.query(
        'UPDATE personnel_appointment SET '
          + 'appointment_type = COALESCE(CAST(:appointmentType AS varchar), appointment_type), '
          + 'appointment_date = COALESCE(CAST(:appointmentDate AS date), appointment_date), '
          + 'department_id = COALESCE(CAST(:departmentId AS bigint), department_id), '
          + 'new_position_name = COALESCE(CAST(:newPositionName AS varchar), new_position_name), '
          + 'status = COALESCE(CAST(:status AS varchar), status), '
          + "processed_date = CASE WHEN CAST(:status AS varchar) = '처리완료' THEN CURRENT_DATE ELSE processed_date END, "
          + "processed_by = CASE WHEN CAST(:status AS varchar) = '처리완료' THEN CAST(:userId AS bigint) ELSE processed_by END, "
          + 'updated_at = now() '
          + 'WHERE personnel_appointment_id = CAST(:id AS bigint) '
          + 'RETURNING personnel_appointment_id AS "personnelAppointmentId", status AS "status"',
        {
          id,
          appointmentType,
          appointmentDate,
          departmentId,
          newPositionName,
          status,
          userId: user.id,
        },
      );
      return rows[0];
    });
  }
}

