import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Pager,
  RefName,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['대기', '대기'],
  ['승인', '승인'],
  ['처리완료', '처리완료'],
];

export default function FnSfr01302Page({ role, notify }: PageProps) {
  const [statusDraft, setStatusDraft] = useState('');
  const [employeeDraft, setEmployeeDraft] = useState<number | string>('');
  const [applied, setApplied] = useState<{ status: string; employeeId: number | string }>({ status: '', employeeId: '' });
  const [pageNo, setPageNo] = useState(0);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/personnel-appointments', role, undefined, {
      status: applied.status,
      employeeId: applied.employeeId,
      page: pageNo,
      size: 20,
    }),
    [role, applied, pageNo],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/personnel-appointments', role, undefined, { status: '대기', page: 0, size: 5 }),
    [role],
  );

  const refresh = () => {
    list.reload();
    pending.reload();
  };

  const columns: Column[] = [
    { key: 'personnelAppointmentId', label: '인사발령 ID' },
    {
      key: 'employeeId',
      label: '대상 임직원',
      render: (row) => <RefName table='employee' role={role} value={row['employeeId']} />,
    },
    { key: 'appointmentType', label: '발령 구분' },
    { key: 'appointmentDate', label: '발령일자', render: (row) => <DateText value={row['appointmentDate']} /> },
    { key: 'newPositionName', label: '발령 후 직위' },
    { key: 'status', label: '발령 상태', render: (row) => <Badge value={row['status']} /> },
    {
      key: 'approvalDocumentId',
      label: '결재문서',
      render: (row) => (row['approvalDocumentId']
        ? <RefName table='approval_document' role={role} value={row['approvalDocumentId']} />
        : <span>-</span>),
    },
    {
      key: 'action',
      label: '처리',
      render: (row) => (row['status'] !== '처리완료'
        ? (
          <button
            type='button'
            onClick={(e) => {
              e.stopPropagation();
              setEditing(row);
            }}
          >
            수정·상태 변경
          </button>
        )
        : <span>-</span>),
    },
  ];

  const pendingColumns: Column[] = [
    {
      key: 'employeeId',
      label: '대상 임직원',
      render: (row) => <RefName table='employee' role={role} value={row['employeeId']} />,
    },
    { key: 'appointmentDate', label: '발령일자', render: (row) => <DateText value={row['appointmentDate']} /> },
  ];

  return (
    <div className='bento'>
      <section className='box span-8'>
        <h2>발령 대상자</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied({ status: statusDraft, employeeId: employeeDraft });
          }}
          onReset={() => {
            setStatusDraft('');
            setEmployeeDraft('');
            setPageNo(0);
            setApplied({ status: '', employeeId: '' });
          }}
        >
          <Field label='발령 상태'>
            <Select value={statusDraft} onChange={setStatusDraft} options={STATUS_OPTIONS} placeholder='전체' />
          </Field>
          <Field label='대상 임직원'>
            <LookupSelect table='employee' role={role} value={employeeDraft} onChange={setEmployeeDraft} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type='button' onClick={() => setCreating(true)}>대상자 등록</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable columns={columns} rows={list.data?.items ?? []} empty='발령 대상자가 없습니다.' />
        <Pager
          page={list.data?.page ?? 0}
          size={list.data?.size ?? 20}
          total={list.data?.total ?? 0}
          onPage={setPageNo}
        />
      </section>
      <section className='box span-4'>
        <h2>처리 대기</h2>
        <Band total={pending.data?.total} />
        <DataTable columns={pendingColumns} rows={pending.data?.items ?? []} empty='대기 중인 대상자가 없습니다.' />
      </section>
      {creating ? (
        <CreateDrawer
          role={role}
          onClose={() => setCreating(false)}
          onDone={() => {
            setCreating(false);
            notify('인사발령 대상자를 등록했습니다.');
            refresh();
          }}
        />
      ) : null}
      {editing ? (
        <EditDrawer
          role={role}
          row={editing}
          onClose={() => setEditing(null)}
          onDone={() => {
            setEditing(null);
            notify('인사발령 대상자를 수정했습니다.');
            refresh();
          }}
        />
      ) : null}
    </div>
  );
}

function CreateDrawer({ role, onClose, onDone }: { role: string; onClose: () => void; onDone: () => void }) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [appointmentType, setAppointmentType] = useState('');
  const [appointmentDate, setAppointmentDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [newPositionName, setNewPositionName] = useState('');

  return (
    <Drawer title='인사발령 대상자 등록' onClose={onClose}>
      <Form
        submit='등록'
        onSubmit={async () => {
          if (employeeId === '') {
            throw new Error('대상 임직원을 선택하세요.');
          }
          if (appointmentType.trim() === '') {
            throw new Error('발령 구분을 입력하세요.');
          }
          if (appointmentDate === '') {
            throw new Error('발령일자를 입력하세요.');
          }
          const body: Row = { employeeId, appointmentType: appointmentType.trim(), appointmentDate };
          if (departmentId !== '') {
            body['departmentId'] = departmentId;
          }
          if (newPositionName.trim() !== '') {
            body['newPositionName'] = newPositionName.trim();
          }
          await call('POST', '/personnel-appointments', role, body);
          onDone();
        }}
      >
        <Field label='대상 임직원' required>
          <LookupSelect table='employee' role={role} value={employeeId} onChange={setEmployeeId} />
        </Field>
        <Field label='발령 구분' required>
          <TextInput value={appointmentType} onChange={setAppointmentType} placeholder='예: 승진, 전보' />
        </Field>
        <Field label='발령일자' required>
          <DateInput value={appointmentDate} onChange={setAppointmentDate} />
        </Field>
        <Field label='발령 후 소속 부서'>
          <LookupSelect table='department' role={role} value={departmentId} onChange={setDepartmentId} />
        </Field>
        <Field label='발령 후 직위'>
          <TextInput value={newPositionName} onChange={setNewPositionName} />
        </Field>
      </Form>
    </Drawer>
  );
}

function EditDrawer({ role, row, onClose, onDone }: { role: string; row: Row; onClose: () => void; onDone: () => void }) {
  const [appointmentType, setAppointmentType] = useState(String(row['appointmentType'] ?? ''));
  const [appointmentDate, setAppointmentDate] = useState(String(row['appointmentDate'] ?? '').slice(0, 10));
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [newPositionName, setNewPositionName] = useState(String(row['newPositionName'] ?? ''));
  const [status, setStatus] = useState(String(row['status'] ?? ''));

  return (
    <Drawer title='인사발령 대상자 수정' onClose={onClose}>
      <Form
        submit='저장'
        note='처리완료로 바꾸면 이후에는 수정할 수 없습니다.'
        onSubmit={async () => {
          if (appointmentType.trim() === '') {
            throw new Error('발령 구분을 입력하세요.');
          }
          if (appointmentDate === '') {
            throw new Error('발령일자를 입력하세요.');
          }
          const body: Row = { appointmentType: appointmentType.trim(), appointmentDate, status };
          if (departmentId !== '') {
            body['departmentId'] = departmentId;
          }
          if (newPositionName.trim() !== '') {
            body['newPositionName'] = newPositionName.trim();
          }
          await call('PATCH', '/personnel-appointments/' + String(row['personnelAppointmentId']), role, body);
          onDone();
        }}
      >
        <Field label='대상 임직원'>
          <RefName table='employee' role={role} value={row['employeeId']} />
        </Field>
        <Field label='발령 구분' required>
          <TextInput value={appointmentType} onChange={setAppointmentType} />
        </Field>
        <Field label='발령일자' required>
          <DateInput value={appointmentDate} onChange={setAppointmentDate} />
        </Field>
        <Field label='발령 후 소속 부서' hint='비워 두면 기존 값을 유지합니다.'>
          <LookupSelect table='department' role={role} value={departmentId} onChange={setDepartmentId} />
        </Field>
        <Field label='발령 후 직위'>
          <TextInput value={newPositionName} onChange={setNewPositionName} />
        </Field>
        <Field label='발령 상태' required>
          <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} />
        </Field>
      </Form>
    </Drawer>
  );
}
